'use client';

import { createContext, useContext, useState, useEffect, ReactNode, useCallback, useRef } from 'react';
import { authFetch, API_URL } from '@/lib/api';
import { setUserId, clearUserId } from '@/lib/analytics/gtag';
import { useCookieConsent } from '@/context/CookieConsentContext';

interface AuthContextType {
    user: UserInfo | null;
    isAuthenticated: boolean;
    isLoading: boolean;
    login: (email: string, password: string, rememberMe?: boolean, turnstileToken?: string) => Promise<{ success: boolean; error?: string; code?: string; role?: string; access_token?: string; requireCaptcha?: boolean; blocked?: boolean; retryAfter?: number }>;
    register: (name: string, email: string, password: string, turnstileToken?: string) => Promise<RegisterResponse>;
    /** Log-in the user directly from verification data (after OTP verified and accounts created) */
    loginFromVerification: (customerData: Record<string, unknown>) => void;
    socialLogin: (clerkToken: string) => Promise<{ success: boolean; error?: string; is_new_user?: boolean; account_linked?: boolean; pending_verification?: boolean; customer_id?: string; email?: string; full_name?: string }>;
    logout: () => void;
    /** Update partial user info (like avatar_url) dynamically in cache and context */
    updateUser: (updates: Partial<UserInfo>) => void;
    /** Register callbacks that run after login/logout so Carts + Wishlist can react */
    onAuthChange: (cb: AuthChangeCallback) => () => void;
}

type AuthChangeCallback = (event: 'login' | 'logout', user: UserInfo | null) => void;

interface RegisterResponse {
    success: boolean;
    email?: string;
    requires_verification?: boolean;
    error?: string;
    requireCaptcha?: boolean;
}

interface UserInfo {
    id: string;
    name: string;
    email: string;
    role?: string;
    avatar_url?: string;
    auth_method?: string;
    is_email_verified?: boolean;
    is_mobile_verified?: boolean;
    phone?: string;
    loyalty_tier?: string;
    wallet_balance?: number;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);
// API_URL imported from @/lib/api
const USER_KEY = 'vedashi_user';
// SECURITY: No TOKEN_KEY — access tokens are handled exclusively via HttpOnly cookies

/** Map backend customer shape → frontend UserInfo */
function toUserInfo(customer: Record<string, unknown>): UserInfo {
    return {
        id: (customer.customer_id ?? customer.id ?? '') as string,
        name: (customer.full_name ?? customer.name ?? '') as string,
        email: (customer.email ?? '') as string,
        role: (customer.role as string) || 'customer',
        avatar_url: (customer.avatar_url as string) || undefined,
        auth_method: (customer.auth_method as string) || undefined,
        is_email_verified: !!(customer.is_email_verified),
        is_mobile_verified: !!(customer.is_mobile_verified),
        phone: (customer.phone ?? customer.mobile_phone ?? '') as string,
        loyalty_tier: (customer.loyalty_tier as string) || 'Bronze',
        wallet_balance: Number(customer.wallet_balance || 0),
    };
}

export function AuthProvider({ children }: { children: ReactNode }) {
    const [user, setUser] = useState<UserInfo | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const listenersRef = useRef<Set<AuthChangeCallback>>(new Set());
    const { consent } = useCookieConsent();

    /** Helper: push user_id to dataLayer only if analytics consent is granted */
    const pushUserId = useCallback((userId: string) => {
        if (consent?.analytics) setUserId(userId);
    }, [consent]);

    /** Helper: clear user_id from dataLayer only if analytics consent is granted */
    const pushClearUserId = useCallback(() => {
        if (consent?.analytics) clearUserId();
    }, [consent]);

    /** Subscribe to auth events — returns unsubscribe function */
    const onAuthChange = useCallback((cb: AuthChangeCallback) => {
        listenersRef.current.add(cb);
        return () => { listenersRef.current.delete(cb); };
    }, []);

    const notifyListeners = useCallback((event: 'login' | 'logout', u: UserInfo | null) => {
        listenersRef.current.forEach(cb => cb(event, u));
    }, []);

    // ── Listen for session-expired event (from authFetch interceptor) ──
    useEffect(() => {
        if (typeof window === 'undefined') return;
        const handler = () => {
            setUser(null);
            localStorage.removeItem(USER_KEY);
            sessionStorage.removeItem('justSignedIn');
            sessionStorage.removeItem('social_otp_data');
            pushClearUserId();
            notifyListeners('logout', null);
        };
        window.addEventListener('session-expired', handler);
        return () => window.removeEventListener('session-expired', handler);
    }, [notifyListeners]);

    // On mount: try to restore session from localStorage cache + validate with server
    useEffect(() => {
        if (typeof window === 'undefined') {
            setIsLoading(false);
            return;
        }

        const stored = localStorage.getItem(USER_KEY);
        if (stored) {
            try {
                const cachedUser: UserInfo = JSON.parse(stored);
                setUser(cachedUser);
                // Push user_id for analytics (consent-gated)
                pushUserId(cachedUser.id);
                // Notify listeners (Cart/Wishlist) about restored session
                setTimeout(() => notifyListeners('login', cachedUser), 0);

                // Validate session with server via HttpOnly cookie
                authFetch(`${API_URL}/api/auth/me`)
                    .then(res => res.json())
                    .then(json => {
                        if (json.success && json.data) {
                            const updatedUser = toUserInfo(json.data);
                            
                            // ── SECURITY ROLE CHECK ──────────────────────────
                            // Prevent admins from using the storefront app as a user
                            if (['admin', 'Super Admin', 'owner'].includes(updatedUser.role || '')) {
                                console.warn('[Auth] Admin role detected in storefront - clearing session');
                                setUser(null);
                                localStorage.removeItem(USER_KEY);
                                notifyListeners('logout', null);
                                return;
                            }
                            
                            setUser(updatedUser);
                            localStorage.setItem(USER_KEY, JSON.stringify(updatedUser));
                            // Re-push user_id with verified data
                            pushUserId(updatedUser.id);
                        } else {
                            // Cookie expired or invalid — clear cached user
                            setUser(null);
                            localStorage.removeItem(USER_KEY);
                            pushClearUserId();
                            notifyListeners('logout', null);
                        }
                    }).catch(() => {
                        // Network error — keep cached user for offline resilience
                    }).finally(() => {
                        setIsLoading(false);
                    });
            } catch {
                localStorage.removeItem(USER_KEY);
                setIsLoading(false);
            }
        } else {
             // ── SILENT RECOVERY CHECK ──────────────────────────
             // If no local storage but cookies exist, try to restore customer session
             authFetch(`${API_URL}/api/auth/me`)
                .then(res => res.json())
                .then(json => {
                    if (json.success && json.data) {
                        const updatedUser = toUserInfo(json.data);
                        // ONLY auto-log if it is NOT an admin
                        if (!['admin', 'Super Admin', 'owner'].includes(updatedUser.role || '')) {
                            setUser(updatedUser);
                            localStorage.setItem(USER_KEY, JSON.stringify(updatedUser));
                            pushUserId(updatedUser.id);
                            notifyListeners('login', updatedUser);
                        }
                    }
                })
                .catch(() => {})
                .finally(() => {
                    setIsLoading(false);
                });
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const login = useCallback(async (email: string, password: string, rememberMe: boolean = true, turnstileToken?: string | null) => {
        try {
            const body: Record<string, unknown> = { email, password, remember_me: rememberMe, source: 'storefront' };
            if (turnstileToken) body.turnstile_token = turnstileToken;

            const res = await authFetch(`${API_URL}/api/auth/login`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'include',
                body: JSON.stringify(body),
            });
            const json = await res.json();
            if (res.ok && json.success && json.data?.customer) {
                const u = toUserInfo(json.data.customer);
                
                // ── SECURITY ROLE CHECK ──────────────────────────
                // Prevent admins from being authenticated as customers in the storefront state
                if (['admin', 'Super Admin', 'owner'].includes(u.role || '')) {
                    console.info('[Auth] Admin login detected - returning success for redirection');
                    // We return success: true so the login page can redirect to the admin panel,
                    // but we DO NOT call setUser(u) or store the user locally.
                    return { success: true, role: u.role };
                }
                
                setUser(u);
                localStorage.setItem(USER_KEY, JSON.stringify(u));
                // SECURITY: No token stored — access token is in HttpOnly cookie
                sessionStorage.setItem('justSignedIn', String(Date.now()));
                pushUserId(u.id);
                notifyListeners('login', u);
                return { success: true, role: u.role };
            }
            if (json.message) return {
                success: false,
                error: json.message,
                code: json.code,
                requireCaptcha: json.requireCaptcha,
                blocked: json.blocked,
                retryAfter: json.retryAfter,
            };
        } catch (err) {
            console.error('[Auth] Login error:', err);
        }

        return { success: false, error: 'Login failed. Please check your credentials.' };
    }, [notifyListeners]);

    const register = useCallback(async (
        name: string,
        email: string,
        password: string,
        turnstileToken?: string
    ): Promise<RegisterResponse> => {
        try {
            const res = await authFetch(`${API_URL}/api/auth/initiate-registration`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'include',
                body: JSON.stringify({ full_name: name, email, password, turnstile_token: turnstileToken }),
            });
            const json = await res.json();
            if (res.ok && json.success) {
                return {
                    success: true,
                    email: json.data?.email || email,
                    requires_verification: true,
                };
            }
            if (json.message) return { success: false, error: json.message, requireCaptcha: json.requireCaptcha };
        } catch (err) {
            console.error('[Auth] Register error:', err);
        }

        return { success: false, error: 'Registration failed. Please try again.' };
    }, []);

    /** Log in the user from verification page data (after OTP created the account) */
    const loginFromVerification = useCallback((customerData: Record<string, unknown>) => {
        const u = toUserInfo(customerData);
        setUser(u);
        localStorage.setItem(USER_KEY, JSON.stringify(u));
        // SECURITY: No token stored — access token is in HttpOnly cookie
        sessionStorage.setItem('justSignedIn', String(Date.now()));
        pushUserId(u.id);
        notifyListeners('login', u);
    }, [notifyListeners, pushUserId]);

    /** Update user fields dynamically */
    const updateUser = useCallback((updates: Partial<UserInfo>) => {
        setUser(prev => {
            if (!prev) return null;
            const updated = { ...prev, ...updates };
            localStorage.setItem(USER_KEY, JSON.stringify(updated));
            // Trigger login event to simulate an update broadcast
            // Notify listeners outside the state updater to avoid React update errors
            setTimeout(() => notifyListeners('login', updated), 0);
            return updated;
        });
    }, [notifyListeners]);

    const logout = useCallback(() => {
        authFetch(`${API_URL}/api/auth/logout`, { method: 'POST', credentials: 'include' }).catch(() => { });
        setUser(null);
        localStorage.removeItem(USER_KEY);
        // Clear all auth-related session storage
        sessionStorage.removeItem('justSignedIn');
        sessionStorage.removeItem('social_otp_data');
        // SECURITY: HttpOnly cookies are cleared server-side by the /api/auth/logout endpoint
        pushClearUserId();
        notifyListeners('logout', null);
    }, [notifyListeners, pushClearUserId]);

    /** Social login via Clerk token → backend JWT (or pending OTP for new users) */
    const socialLogin = useCallback(async (clerkToken: string) => {
        try {
            const res = await authFetch(`${API_URL}/api/auth/social/login`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'include',
                body: JSON.stringify({ clerk_token: clerkToken }),
            });
            const json = await res.json();

            // New user → pending OTP verification (no JWT yet)
            if (res.ok && json.success && json.pending_verification) {
                return {
                    success: true,
                    pending_verification: true,
                    customer_id: json.data.customer_id,
                    email: json.data.email,
                    full_name: json.data.full_name,
                };
            }

            // Returning user → JWT issued as HttpOnly cookie
            if (res.ok && json.success && json.data?.customer) {
                const u = toUserInfo(json.data.customer);
                setUser(u);
                localStorage.setItem(USER_KEY, JSON.stringify(u));
                // SECURITY: No token stored — access token is in HttpOnly cookie
                sessionStorage.setItem('justSignedIn', String(Date.now()));
                pushUserId(u.id);
                notifyListeners('login', u);
                return {
                    success: true,
                    is_new_user: json.data.is_new_user,
                    account_linked: json.data.account_linked,
                };
            }
            return { success: false, error: json.message || 'Social login failed' };
        } catch (err) {
            console.error('[Auth] Social login error:', err);
            return { success: false, error: 'Social login failed. Please try again.' };
        }
    }, [notifyListeners]);


    return (
        <AuthContext.Provider value={{
            user, isAuthenticated: !!user, isLoading,
            login, register, loginFromVerification, socialLogin, logout, updateUser, onAuthChange,
        }}>
            {children}
        </AuthContext.Provider>
    );
}

export function useAuth() {
    const context = useContext(AuthContext);
    if (!context) throw new Error('useAuth must be used within AuthProvider');
    return context;
}

'use client';

import { createContext, useContext, useState, useCallback, useEffect, ReactNode, useRef } from 'react';
import { BackendCartItem, BackendCart } from '@/types';
import { useAuth } from '@/context/AuthContext';
import { trackEcommerce } from '@/lib/analytics/gtag';
import {
    createCart as apiCreateCart,
    getCart as apiGetCart,
    addCartItem as apiAddCartItem,
    updateCartItem as apiUpdateCartItem,
    removeCartItem as apiRemoveCartItem,
    mergeGuestCart as apiMergeGuestCart,
    validateCoupon as apiValidateCoupon,
    getBestAutoApplyCoupon as apiGetBestAutoApplyCoupon,
    saveForLater as apiSaveForLater,
    moveToCartFromSaved as apiMoveToCart,
    getSavedItems as apiGetSavedItems,
} from '@/lib/api';

const GUEST_CART_KEY = 'ksp_guest_cart_id';

interface CartContextType {
    items: BackendCartItem[];
    savedItems: BackendCartItem[];
    cartId: string | null;
    loading: boolean;
    error: string | null;
    addItem: (productId: string, variantId: string | null, quantity?: number) => Promise<void>;
    removeItem: (cartItemId: string) => Promise<void>;
    updateQuantity: (cartItemId: string, quantity: number) => Promise<void>;
    clearCart: (localOnly?: boolean) => Promise<void>;
    saveForLater: (cartItemId: string) => Promise<void>;
    moveToCart: (cartItemId: string) => Promise<void>;
    totalItems: number;
    totalPrice: number;
    couponCode: string | null;
    couponDiscount: number;
    couponType: string | null;
    couponError: string | null;
    applyCoupon: (code: string) => Promise<boolean>;
    removeCoupon: () => void;
    orderNotes: string;
    setOrderNotes: (notes: string) => void;
}

const CartContext = createContext<CartContextType | undefined>(undefined);

/** Flatten backend cart item → easy-to-consume shape with top-level product_id, product_name, price */
function flattenCartItem(item: BackendCartItem): BackendCartItem {
    return {
        ...item,
        product_id: item.product?.product_id || item.product_id || '',
        product_name: item.product?.product_name || item.product_name || 'Product',
        slug: item.product?.slug || item.slug || '',
        sku: item.variant?.variant_sku || item.product?.product_sku || item.sku || (item as unknown as Record<string, unknown>).product_sku as string || '',
        price: item.pricing?.effective_price ?? item.pricing?.unit_price ?? item.price ?? 0,
        original_price: item.pricing?.unit_price ?? item.price ?? 0,
        size_label: item.variant?.size_label || item.size_label || '',
        image_url: item.product?.thumbnail_url || item.image_url || '',
        stock_quantity: item.variant?.stock_quantity ?? (item as unknown as Record<string, unknown>).stock_quantity as number ?? 0,
    };
}

export function CartProvider({ children }: { children: ReactNode }) {
    const [items, setItems] = useState<BackendCartItem[]>([]);
    const [savedItems, setSavedItems] = useState<BackendCartItem[]>([]);
    const [cartId, setCartId] = useState<string | null>(null);
    const [totalItems, setTotalItems] = useState(0);
    const [totalPrice, setTotalPrice] = useState(0);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [couponCode, setCouponCode] = useState<string | null>(null);
    const [couponDiscount, setCouponDiscount] = useState(0);
    const [couponType, setCouponType] = useState<string | null>(null);
    const [couponError, setCouponError] = useState<string | null>(null);
    const [autoApplyDisabled, setAutoApplyDisabled] = useState(false);
    const [orderNotes, setOrderNotes] = useState('');
    const { onAuthChange, isAuthenticated, user } = useAuth();
    const initDone = useRef(false);

    const fetchSavedItems = useCallback(async (cId: string) => {
        try {
            const res = await apiGetSavedItems(cId);
            if (res.success && res.data) {
                setSavedItems((res.data || []).map(flattenCartItem));
            }
        } catch (err) {
            console.error('[CartContext] fetchSavedItems error:', err);
        }
    }, []);

    /** Fetch full cart state from backend */
    const fetchCart = useCallback(async (cId: string): Promise<BackendCart | undefined> => {
        try {
            const res = await apiGetCart({ cart_id: cId });
            if (res.success && res.data) {
                const cart = res.data as BackendCart;
                const flatItems = (cart.items || []).map(flattenCartItem);
                setItems(flatItems);
                setTotalItems(cart.summary?.item_count ?? cart.total_items ?? flatItems.reduce((s: number, i: BackendCartItem) => s + i.quantity, 0));
                setTotalPrice(cart.summary?.grand_total || cart.total_amount || flatItems.reduce((s: number, i: BackendCartItem) => s + (i.price || 0) * i.quantity, 0));
                await fetchSavedItems(cId);
                return cart;
            }
        } catch (err) {
            console.error('[CartContext] fetchCart error:', err);
        }
    }, [fetchSavedItems]);

    /** Initialize cart for a logged-in customer (optionally merging a guest cart first) */
    const initCart = useCallback(async (customerId: string) => {
        setLoading(true);
        setError(null);
        try {
            // Check if there's a guest cart to merge
            const guestCartId = typeof window !== 'undefined' ? localStorage.getItem(GUEST_CART_KEY) : null;
            if (guestCartId) {
                try {
                    await apiMergeGuestCart(guestCartId, customerId);
                } catch (mergeErr) {
                    console.warn('[CartContext] Guest cart merge failed (cart may have expired):', mergeErr);
                }
                localStorage.removeItem(GUEST_CART_KEY);
            }

            const getRes = await apiGetCart({ customer_id: customerId });
            if (getRes.success && getRes.data) {
                const cart = getRes.data as BackendCart;
                setCartId(cart.cart_id);
                const flatItems = (cart.items || []).map(flattenCartItem);
                setItems(flatItems);
                setTotalItems(cart.summary?.item_count ?? cart.total_items ?? flatItems.reduce((s: number, i: BackendCartItem) => s + i.quantity, 0));
                setTotalPrice(cart.summary?.grand_total ?? cart.total_amount ?? flatItems.reduce((s: number, i: BackendCartItem) => s + (i.price || 0) * i.quantity, 0));
                await fetchSavedItems(cart.cart_id);
            } else {
                const createRes = await apiCreateCart(customerId);
                if (createRes.success && createRes.data) {
                    setCartId(createRes.data.cart_id);
                    setItems([]);
                    setSavedItems([]);
                    setTotalItems(0);
                    setTotalPrice(0);
                }
            }
        } catch (err) {
            console.error('[CartContext] initCart error:', err);
            setError('Failed to load cart');
        } finally {
            setLoading(false);
        }
    }, []);

    /** Restore a guest cart from localStorage (if user is NOT authenticated) */
    const restoreGuestCart = useCallback(async () => {
        if (typeof window === 'undefined') return;
        const savedCartId = localStorage.getItem(GUEST_CART_KEY);
        if (!savedCartId) return;

        setLoading(true);
        try {
            const res = await apiGetCart({ cart_id: savedCartId });
            if (res.success && res.data) {
                const cart = res.data as BackendCart;
                setCartId(cart.cart_id);
                const flatItems = (cart.items || []).map(flattenCartItem);
                setItems(flatItems);
                setTotalItems(cart.summary?.item_count ?? cart.total_items ?? flatItems.reduce((s: number, i: BackendCartItem) => s + i.quantity, 0));
                setTotalPrice(cart.summary?.grand_total ?? cart.total_amount ?? flatItems.reduce((s: number, i: BackendCartItem) => s + (i.price || 0) * i.quantity, 0));
                await fetchSavedItems(cart.cart_id);
            } else {
                // Guest cart expired or deleted — clean up
                localStorage.removeItem(GUEST_CART_KEY);
            }
        } catch (err) {
            console.error('[CartContext] restoreGuestCart error:', err);
            localStorage.removeItem(GUEST_CART_KEY);
        } finally {
            setLoading(false);
        }
    }, []);

    /** Create a guest cart on-the-fly (called when a guest clicks "Add to Cart") */
    const ensureGuestCart = useCallback(async (): Promise<string | null> => {
        try {
            const createRes = await apiCreateCart(); // no customer_id → guest cart
            if (createRes.success && createRes.data) {
                const newCartId = createRes.data.cart_id;
                setCartId(newCartId);
                localStorage.setItem(GUEST_CART_KEY, newCartId);
                return newCartId;
            }
        } catch (err) {
            console.error('[CartContext] ensureGuestCart error:', err);
        }
        return null;
    }, []);

    const resetCart = useCallback(() => {
        setCartId(null);
        setItems([]);
        setSavedItems([]);
        setTotalItems(0);
        setTotalPrice(0);
        setError(null);
        setCouponCode(null);
        setCouponDiscount(0);
        setCouponType(null);
        setCouponError(null);
        setAutoApplyDisabled(false);
        if (typeof window !== 'undefined') {
            localStorage.removeItem(GUEST_CART_KEY);
        }
        setOrderNotes('');
    }, []);

    const applyCoupon = useCallback(async (code: string): Promise<boolean> => {
        setCouponError(null);
        try {
            // Compute cart_total from items directly to avoid stale totalPrice state
            const computedCartTotal = items.reduce((sum, item) => sum + (item.price || 0) * item.quantity, 0);
            const cartTotalToSend = computedCartTotal > 0 ? computedCartTotal : totalPrice;

            if (!cartTotalToSend || cartTotalToSend <= 0) {
                setCouponError('Please add items to your cart before applying a coupon');
                return false;
            }

            const res = await apiValidateCoupon(code, cartTotalToSend);
            if (res.success) {
                setCouponCode(res.data.coupon.code);
                setCouponType(res.data.coupon.discount_type || null);

                let computedDiscount = 0;

                if (res.data.coupon.discount_type === 'bogo') {
                    const buyQty = res.data.coupon.bogo_buy_qty || 1;
                    const getQty = res.data.coupon.bogo_get_qty || 1;

                    const flatPrices: number[] = [];
                    items.forEach(it => {
                        for (let i = 0; i < it.quantity; i++) {
                            // Effective price
                            flatPrices.push(it.price || 0);
                        }
                    });

                    flatPrices.sort((a, b) => a - b);
                    const bogoGroups = Math.floor(flatPrices.length / (buyQty + getQty));
                    const freeItemsCount = bogoGroups * getQty;

                    let bogoDiscount = 0;
                    for (let i = 0; i < freeItemsCount; i++) {
                        bogoDiscount += flatPrices[i];
                    }

                    if (res.data.coupon.max_discount_cap !== null) {
                        bogoDiscount = Math.min(bogoDiscount, parseFloat(res.data.coupon.max_discount_cap));
                    }
                    computedDiscount = bogoDiscount;
                } else {
                    computedDiscount = res.data.discount;
                }

                // Enforce minimum payable of ₹1 — cap discount so total never drops below ₹MINIMUM_PAYABLE
                const minPayable = Number(process.env.NEXT_PUBLIC_MINIMUM_PAYABLE_AMOUNT) || 1;
                const maxAllowedDiscount = Math.max(0, cartTotalToSend - minPayable);
                computedDiscount = Math.min(computedDiscount, maxAllowedDiscount);

                setCouponDiscount(computedDiscount);
                return true;
            } else {
                setCouponError(res.message || 'Invalid coupon');
                setCouponCode(null);
                setCouponDiscount(0);
                setCouponType(null);
                return false;
            }
        } catch {
            setCouponError('Failed to validate coupon');
            return false;
        }
    }, [totalPrice, items]);

    const removeCoupon = useCallback(() => {
        setCouponCode(null);
        setCouponDiscount(0);
        setCouponType(null);
        setCouponError(null);
        setAutoApplyDisabled(true); // Don't forcibly auto-apply again if user actively removed it
    }, []);

    // Subscribe to auth changes
    useEffect(() => {
        const unsub = onAuthChange((event, user) => {
            if (event === 'login' && user) {
                initCart(user.id);
            } else if (event === 'logout') {
                resetCart();
            }
        });
        return unsub;
    }, [onAuthChange, initCart, resetCart]);

    // On mount: if not authenticated, try to restore guest cart
    useEffect(() => {
        if (initDone.current) return;
        initDone.current = true;

        // If user is already authenticated, initCart is handled by onAuthChange listener
        // If not authenticated, try to restore a guest cart from localStorage
        if (!isAuthenticated) {
            restoreGuestCart();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    // Auto-apply effect
    useEffect(() => {
        if (couponCode || totalPrice <= 0 || autoApplyDisabled) return;

        let active = true;
        apiGetBestAutoApplyCoupon(totalPrice)
            .then(res => {
                if (active && res.success && res.data?.coupon?.code) {
                    // Temporarily skip setCouponError on this automatic background attempt
                    applyCoupon(res.data.coupon.code).catch(() => { });
                }
            })
            .catch(() => { });

        return () => { active = false; };
    }, [totalPrice, couponCode, autoApplyDisabled, applyCoupon]);


    // Re-validate applied coupon when cart changes
    useEffect(() => {
        if (couponCode && !loading) {
            applyCoupon(couponCode).catch(err => {
                console.warn('[CartContext] Coupon re-validation failed:', err);
            });
        }
        // We only want to re-run this when items or total price changes to keep discount accurate
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [items.length, totalPrice]);

    const addItem = useCallback(async (productId: string, variantId: string | null, quantity = 1) => {
        let activeCartId = cartId;

        // If no cart exists, create one (guest cart if not authenticated)
        if (!activeCartId) {
            if (isAuthenticated && user) {
                // Shouldn't normally happen, but just in case
                const createRes = await apiCreateCart(user.id);
                if (createRes.success && createRes.data) {
                    activeCartId = createRes.data.cart_id;
                    setCartId(activeCartId);
                }
            } else {
                activeCartId = await ensureGuestCart();
            }
        }

        if (!activeCartId) {
            setError('Failed to create cart. Please try again.');
            return;
        }

        setLoading(true);
        setError(null);
        try {
            if (variantId) {
                await apiAddCartItem(activeCartId, variantId, quantity, true);
            } else {
                await apiAddCartItem(activeCartId, productId, quantity, false);
            }
            const freshCart = await fetchCart(activeCartId);
            const freshItems = freshCart ? (freshCart.items || []).map(flattenCartItem) : [];
            const addedItem = freshItems.find(i => 
                String(i.product_id) === String(productId) && 
                (variantId ? String(i.variant_id) === String(variantId) : true)
            );

            if (addedItem) {
                trackEcommerce('add_to_cart', {
                    currency: 'INR',
                    value: (addedItem.price || 0) * quantity,
                    items: [{
                        item_id: String(addedItem.product_id || productId),
                        item_name: addedItem.product_name || productId,
                        price: addedItem.price || 0,
                        quantity,
                    }],
                });
            } else {
                // Fallback: Fire the event with the data we already know
                trackEcommerce('add_to_cart', {
                    currency: 'INR',
                    value: 0, // Fallback value
                    items: [{
                        item_id: String(productId),
                        item_name: productId,
                        price: 0, // Fallback price
                        quantity,
                    }],
                });
            }
        } catch (err) {
            console.error('[CartContext] addItem error:', err);
            const msg = 'Failed to add item to cart';
            setError(msg);
            throw err; // Re-throw to inform caller (e.g. for toast handling)
        } finally {
            setLoading(false);
        }
    }, [cartId, fetchCart, isAuthenticated, user, ensureGuestCart]);

    const updateQuantity = useCallback(async (cartItemId: string, quantity: number) => {
        if (quantity <= 0) {
            await apiRemoveCartItem(cartItemId);
            if (cartId) await fetchCart(cartId);
            return;
        }
        setLoading(true);
        setError(null);
        try {
            await apiUpdateCartItem(cartItemId, quantity);
            if (cartId) await fetchCart(cartId);
        } catch (err) {
            console.error('[CartContext] updateQuantity error:', err);
            setError('Failed to update quantity');
        } finally {
            setLoading(false);
        }
    }, [cartId, fetchCart]);

    const removeItem = useCallback(async (cartItemId: string) => {
        // Capture item data BEFORE removal for the GA4 event
        const removedItem = items.find(i => i.cart_item_id === cartItemId);

        setLoading(true);
        setError(null);
        try {
            await apiRemoveCartItem(cartItemId);
            if (cartId) await fetchCart(cartId);

            // GA4: remove_from_cart
            if (removedItem) {
                trackEcommerce('remove_from_cart', {
                    currency: 'INR',
                    value: (removedItem.price || 0) * removedItem.quantity,
                    items: [{
                        item_id: removedItem.product_id || '',
                        item_name: removedItem.product_name || 'Product',
                        price: removedItem.price || 0,
                        quantity: removedItem.quantity,
                    }],
                });
            }
        } catch (err) {
            console.error('[CartContext] removeItem error:', err);
            setError('Failed to remove item');
        } finally {
            setLoading(false);
        }
    }, [cartId, fetchCart, items]);

    const saveForLater = useCallback(async (cartItemId: string) => {
        setLoading(true);
        setError(null);
        try {
            await apiSaveForLater(cartItemId);
            if (cartId) await fetchCart(cartId);
        } catch (err) {
            console.error('[CartContext] saveForLater error:', err);
            setError('Failed to save item for later');
        } finally {
            setLoading(false);
        }
    }, [cartId, fetchCart]);

    const moveToCart = useCallback(async (cartItemId: string) => {
        setLoading(true);
        setError(null);
        try {
            await apiMoveToCart(cartItemId);
            if (cartId) await fetchCart(cartId);
        } catch (err) {
            console.error('[CartContext] moveToCart error:', err);
            setError('Failed to move item to cart');
        } finally {
            setLoading(false);
        }
    }, [cartId, fetchCart]);

    const clearCart = useCallback(async (localOnly = false) => {
        if (!cartId) return;
        setLoading(true);
        try {
            if (!localOnly) {
                for (const item of items) {
                    await apiRemoveCartItem(item.cart_item_id);
                }
            }
            setItems([]);
            setTotalItems(0);
            setTotalPrice(0);
        } catch (err) {
            console.error('[CartContext] clearCart error:', err);
        } finally {
            setLoading(false);
        }
    }, [cartId, items]);

    // Real-time stock polling & validation
    useEffect(() => {
        if (!cartId || items.length === 0) return;

        // Auto-check quantities against stock
        items.forEach(item => {
            const stock = item.stock_quantity ?? 0;
            if (stock > 0 && item.quantity > stock) {
                updateQuantity(item.cart_item_id, stock).catch(() => {});
                import('react-hot-toast').then(({ default: toast }) => {
                    toast(`Quantity of ${item.product_name} reduced to ${stock} due to limited stock.`, { icon: '⚠️' });
                });
            }
        });

        // Poll cart every 30 seconds
        const pollInterval = setInterval(() => {
            fetchCart(cartId).catch(() => {});
        }, 30000);

        return () => clearInterval(pollInterval);
    }, [cartId, items, fetchCart, updateQuantity]);

    return (
        <CartContext.Provider value={{
            items, savedItems, cartId, loading, error,
            addItem, removeItem, updateQuantity, clearCart, saveForLater, moveToCart,
            totalItems, totalPrice,
            couponCode, couponDiscount, couponType, couponError,
            applyCoupon, removeCoupon,
            orderNotes, setOrderNotes,
        }}>
            {children}
        </CartContext.Provider>
    );
}

export function useCart() {
    const context = useContext(CartContext);
    if (!context) throw new Error('useCart must be used within CartProvider');
    return context;
}

